    "etymology": "Issu du moyen haut-allemand « dō / dā », vieux haut-allemand « dō » (alors, lorsque) et « dār » (là). Proto-germanique *þō / *þar, déictique temporel et spatial issu de la racine pronominale indo-européenne *to-.",
